-- ETRANOM v181 Wizard party skill catalog — part 6/6.
begin;
on conflict(specialization_key,skill_id) do update set skill_data=excluded.skill_data,enabled=true;
update public.party_battle_skill_catalog set enabled=false where specialization_key not in ('wizard_arcane_mage','wizard_elementalist','wizard_warlock','wizard_necromancer');
